import { useEffect } from "react";

// Ambient motion budget: infinite loops (marquee, grid scan, prismatic hue
// cycles) pause while their subtree is offscreen, and constrained devices
// get a calmer baseline via the `calm-ambience` document class. One-shot
// animations (sparklines, entrances) are untouched.
//
// Mount once (e.g. in App): a MutationObserver picks up [data-ambient]
// subtrees mounted asynchronously after data loads, so no per-route
// re-run is needed.
export function useAmbientMotion() {
  useEffect(() => {
    try {
      const coarse =
        typeof window.matchMedia === "function" &&
        window.matchMedia("(pointer: coarse)").matches;
      const lowMem =
        typeof navigator.deviceMemory === "number" && navigator.deviceMemory <= 4;
      const saveData = !!navigator.connection?.saveData;
      document.documentElement.classList.toggle(
        "calm-ambience",
        !!(coarse || lowMem || saveData)
      );
    } catch {
      /* non-DOM test env — leave the default full-ambience baseline */
    }

    let observer = null;
    let mutationObserver = null;
    try {
      if (typeof IntersectionObserver === "undefined") return;
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            try {
              entry.target.classList.toggle("ambient-paused", !entry.isIntersecting);
            } catch {
              /* ignore */
            }
          });
        },
        { threshold: 0, rootMargin: "100px" }
      );
      const watch = (root) => {
        try {
          root.querySelectorAll("[data-ambient]").forEach((el) => observer.observe(el));
        } catch {
          /* ignore */
        }
      };
      watch(document);
      if (typeof MutationObserver !== "undefined" && document.body) {
        mutationObserver = new MutationObserver((mutations) => {
          mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
              if (!node || node.nodeType !== 1) return;
              try {
                if (node.matches?.("[data-ambient]")) observer.observe(node);
                node.querySelectorAll?.("[data-ambient]").forEach((el) => observer.observe(el));
              } catch {
                /* ignore */
              }
            });
          });
        });
        mutationObserver.observe(document.body, { childList: true, subtree: true });
      }
    } catch {
      /* observe failures must never break page render */
    }
    return () => {
      try {
        observer?.disconnect();
        mutationObserver?.disconnect();
      } catch {
        /* ignore */
      }
    };
  }, []);
}
