import { fmt, fmtTime } from "./parseItem";

// Shared price-reliability signals. Centralizes the thresholds so every
// surface (detail hero, market rows, compare, saved, lookup) agrees on
// when a displayed median deserves a qualifier. Complements — never
// replaces — the worker-provided confidence label.
//
// Tiers:
//   single  - exactly 1 sample: the "median" is one listing's asking price
//   thin    - 2-4 samples: median exists but is a rough estimate
//   stale   - last observed >7d ago: price may be outdated
//   spread  - IQR width >50% of median: listings disagree widely
//   one-seller - every trail listing is from one seller: thin market

export const THIN_SAMPLE_MAX = 4;
export const STALE_MS = 7 * 24 * 60 * 60 * 1000;
export const WIDE_SPREAD_RATIO = 0.5;

export function getPriceNotices(item, trailSellers = []) {
  if (!item || item.referenceOnly || !(item.median > 0)) return [];
  const notices = [];
  const samples = item.samples || 0;

  if (samples <= 1) {
    notices.push({
      id: "single",
      tone: "amber",
      short: "1 listing",
      full: "Only one observed listing — this is its asking price, not a market average.",
    });
  } else if (samples <= THIN_SAMPLE_MAX) {
    notices.push({
      id: "thin",
      tone: "amber",
      short: "thin data",
      full: `Only ${samples} observed listings — the median is a rough estimate.`,
    });
  }

  if (item.lastSeenMs && Date.now() - item.lastSeenMs > STALE_MS) {
    notices.push({
      id: "stale",
      tone: "red",
      short: "stale",
      full: `Last observed ${fmtTime(item.lastSeenMs)} — may not reflect current prices.`,
    });
  }

  if (item.median > 0 && item.iqrLow > 0 && item.iqrHigh > item.iqrLow) {
    const spread = (item.iqrHigh - item.iqrLow) / item.median;
    if (spread > WIDE_SPREAD_RATIO) {
      notices.push({
        id: "spread",
        tone: "amber",
        short: "wide spread",
        full: `Observed prices vary widely (${fmt(item.iqrLow)}–${fmt(item.iqrHigh)}).`,
      });
    }
  }

  const sellers = Array.isArray(trailSellers)
    ? [...new Set(trailSellers.filter(Boolean))]
    : [];
  if (sellers.length === 1 && samples > 0) {
    notices.push({
      id: "one-seller",
      tone: "amber",
      short: "1 seller",
      full: "All observed listings are from one seller — the price may not reflect the wider market.",
    });
  }

  return notices;
}

// First N notices in priority order for compact list surfaces.
export function topNotices(item, trailSellers = [], max = 2) {
  return getPriceNotices(item, trailSellers).slice(0, max);
}
