import { useEffect, useMemo, useState } from "react";
import { RefreshCw } from "lucide-react";
import { fetchAllChestShops, fetchWarpZones } from "@/lib/castiaClient";
import { exactCoins, parseShopLocation, sameShopPosition } from "@/lib/shopLocation";
import { distinctShopRows, stockLabel, stockTimestamp } from "@/lib/shopStock";
import ShopContextMap from './ShopContextMap';
import ItemSprite from './ItemSprite';
import ItemName from './ItemName';
import { shopItemDisplayName } from '@/lib/shopPresentation';
import { enchantmentLabel, parseItemKey } from '@/lib/parseItem';
import { formatRuneName, romanRuneLevel } from '@/lib/variantPresentation';
import { decorateShopArea } from '@/lib/shopAreas';

let catalogCache = null;

export default function ShopLocationPanel({ locationKey, onClose, onSelect, onCompare }) {
  const target = useMemo(() => parseShopLocation(locationKey), [locationKey]);
  const hasTarget = !!target;
  const [catalog, setCatalog] = useState(null);
  const [zones, setZones] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refresh, setRefresh] = useState(0);

  useEffect(() => {
    if (!hasTarget) { setLoading(false); return; }
    const controller = new AbortController();
    setLoading(true); setError(null);
    const cached = !refresh && catalogCache && Date.now() - catalogCache.at < 60000;
    Promise.all([
      cached ? Promise.resolve(catalogCache.rows) : fetchAllChestShops({ signal: controller.signal }).then(result => distinctShopRows(result.shops)),
      fetchWarpZones({ limit: 500, signal: controller.signal }).then(result => result.zones || []).catch(() => []),
    ]).then(([rows, arrivals]) => {
      if (controller.signal.aborted) return;
      if (!cached) catalogCache = { at: Date.now(), rows };
      setCatalog(rows); setZones(arrivals);
    }).catch(e => { if (!controller.signal.aborted) setError(e.message); })
      .finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [hasTarget, refresh]);

  const observed = target && catalog?.find(row => sameShopPosition(row, target));
  const selected = observed ? decorateShopArea(observed, zones) : null;
  const selectedRarity = selected?.variantKey?.startsWith("oxy2:")
    ? parseItemKey(`${selected.itemName}|v:${selected.variantKey}`).rarity
    : null;
  const replaced = selected && target.signFingerprint && selected.signFingerprint !== target.signFingerprint;
  const buttonClass = "inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2 font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-zinc-300 transition-colors hover:border-indigo-400/50 hover:bg-indigo-500/10 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-indigo-400 disabled:opacity-50";

  return <div className="h-full overflow-y-auto overscroll-contain custom-scrollbar touch-pan-y" data-testid="shop-location-panel">
    <div className="sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-white/10 bg-bg-base/95 px-5 py-3 backdrop-blur-xl sm:px-8">
      <div className="min-w-0"><p className="font-mono text-[10px] uppercase tracking-[0.24em] text-indigo-400">Chest-shop details</p><h2 className="truncate font-heading text-lg font-black tracking-tight">Shop location</h2></div>
      <div className="flex items-center gap-2 shrink-0">
        <button className={buttonClass} aria-label="Refresh shop observations" data-testid="shop-refresh" disabled={loading} onClick={() => setRefresh(value => value + 1)} title="Refresh data"><RefreshCw className={loading ? "h-4 w-4 animate-spin" : "h-4 w-4"}/><span className="hidden sm:inline">Refresh</span></button>
        <button className={buttonClass} aria-label="Close shop details" data-testid="drawer-close" onClick={onClose}>Close</button>
      </div>
    </div>
    <div className="space-y-6 p-6 sm:p-8">
    {!target ? <p>This location link is invalid.</p> : <>
      {loading && (
        <div role="status" aria-label="Loading observed offers" className="py-16">
          <RefreshCw className="mx-auto h-6 w-6 animate-spin text-indigo-400" />
          <p className="mt-3 text-center font-mono text-[11px] uppercase tracking-[0.2em] text-zinc-500">Loading observed offers</p>
          <div className="mx-auto mt-6 max-w-md space-y-2" aria-hidden="true">
            {[0, 1, 2].map((i) => (
              <div key={i} className="flex items-center gap-3 rounded-lg border border-white/10 bg-white/[0.02] p-3">
                <div className="h-7 w-7 animate-pulse rounded-md bg-white/10" />
                <div className="flex-1 space-y-1.5">
                  <div className="h-3 w-2/3 animate-pulse rounded bg-white/10" />
                  <div className="h-2 w-1/3 animate-pulse rounded bg-white/[0.07]" />
                </div>
                <div className="h-3 w-12 animate-pulse rounded bg-white/10" />
              </div>
            ))}
          </div>
        </div>
      )}
      {error && <p role="alert">Could not load this location: {error}</p>}
      {!loading && !error && !selected && <p>No current observation exists at this location. The shop may have moved or may need rescanning.</p>}
      {!loading && !error && selected && <>
        {replaced && <p role="alert" className="border border-amber-400/50 p-3 text-amber-200">The sign has changed since this link was created. These are the current observations, not the original offer.</p>}
        <section className="relative overflow-hidden rounded-2xl border border-indigo-400/30 bg-indigo-500/[0.06] p-5">
          <div className="absolute -right-8 -top-10 h-36 w-36 rounded-full bg-indigo-400/10 blur-3xl" />
          <div className="relative flex items-start justify-between gap-4"><div className="flex items-start gap-3 min-w-0"><ItemSprite item={{ key: selected.itemName || selected.displayItemName, variantKey: selected.variantKey }} size="md" className="mt-0.5" /><div className="min-w-0"><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-indigo-300">Currently Selected Item</p><h3 data-testid="selected-shop-item" className="mt-1 font-heading text-2xl font-black"><ItemName name={shopItemDisplayName(selected)} rarity={selectedRarity} variantKey={selected.variantKey} enchantments={selected.enchantments} layout="wrap" runeDisplay="count" /></h3><p className="mt-1 text-sm text-zinc-300">{selected.seller}</p></div></div></div>
          <div className="relative mt-4 flex flex-wrap items-end justify-between gap-3 border-t border-white/10 pt-4">
            <p className="font-heading text-xl font-black tabular-nums text-indigo-300">{exactCoins(selected.unitPrice)}$ <span className="font-mono text-[10px] font-bold uppercase tracking-wider text-zinc-500">each{selected.buyQuantity > 1 ? ` · ${exactCoins(selected.buyPrice)}$ for ${selected.buyQuantity} items` : ""}</span></p>
            {selected.warpName && <p className="text-sm font-semibold text-[var(--text-primary)]">{selected.warpInferred ? "Nearby " : ""}/pw {selected.warpName}</p>}
          </div>
          {selected.tier > 0 && <p>Tier {selected.tier}</p>}
          {Object.entries(selected.enchantments || {}).length > 0 && <p className="text-sm">{Object.entries(selected.enchantments).map(([name, level]) => /^oxywire:/i.test(name) ? `${formatRuneName(name)} ${romanRuneLevel(level)}` : `${enchantmentLabel(name)} ${level}`).join(" · ")}</p>}
          <div className="mt-3 rounded-lg border border-white/10 bg-bg-base/45 px-3 py-2.5"><p className="font-semibold text-[var(--text-primary)]">{stockLabel(selected)}</p><p className="mt-1 text-xs text-[var(--text-secondary)]">{stockTimestamp(selected)}</p></div>
          {selected.requiresTooltipConfirmation && <p className="text-amber-200">Item identity still needs an in-game confirmation.</p>}
          <button className={`${buttonClass} relative mt-4`} onClick={() => onCompare(selected)}>Compare this item’s offers</button>
        </section>
      </>}
      {!loading && !error && catalog && <ShopContextMap target={target} catalog={catalog} zones={zones} onSelect={onSelect} />}
    </>}
  </div></div>;
}
