import "@/App.css";
import React, { Suspense, useEffect } from "react";
import { BrowserRouter, Routes, Route, Navigate, useLocation } from "react-router-dom";
import { motion, useReducedMotion } from "framer-motion";
import { useAmbientMotion } from "@/lib/useAmbientMotion";
import { MarketProvider } from "@/lib/MarketContext";
import { Toaster } from "@/components/ui/sonner";
import CompareTray from "@/components/landing/CompareTray";
import DetailDrawer from "@/components/landing/DetailDrawer";
import CommandPalette from "@/components/landing/CommandPalette";
import KeyboardHelpModal from "@/components/landing/KeyboardHelpModal";
import BackToTop from "@/components/landing/BackToTop";
import InstallPrompt from "@/components/landing/InstallPrompt";
import VersionPrompt from "@/components/landing/VersionPrompt";
import ErrorBoundary, { InlineFallback } from "@/components/ErrorBoundary";
import PageSkeleton from "@/components/PageSkeleton";

const ListingsPage = React.lazy(() => import("@/pages/ListingsPage"));
const ComparePage = React.lazy(() => import("@/pages/ComparePage"));
const SellersPage = React.lazy(() => import("@/pages/SellersPage"));
const ShopsPage = React.lazy(() => import("@/pages/ShopsPage"));
const SellerDetail = React.lazy(() => import("@/pages/SellerDetail"));
const LegalPage = React.lazy(() => import("@/pages/LegalPage"));
const NotFoundPage = React.lazy(() => import("@/pages/NotFoundPage"));
const ItemDetail = React.lazy(() => import("@/pages/ItemDetail"));
const LookupPage = React.lazy(() => import("@/pages/LookupPage"));
const DashboardPage = React.lazy(() => import("@/pages/Dashboard"));
const SettingsPage = React.lazy(() => import("@/pages/SettingsPage"));
const AdminPage = React.lazy(() => import("@/pages/AdminPage"));
const SavedPage = React.lazy(() => import("@/pages/SavedPage"));
// Dev-only export-card matrix. The route is gated on NODE_ENV below so the
// harness can never ship to production; lazy so it stays out of the main
// bundle even in development until visited.
const DevCards = process.env.NODE_ENV !== "production"
  ? React.lazy(() => import("@/pages/DevCards"))
  : null;
const DevSpriteLab = process.env.NODE_ENV !== "production"
  ? React.lazy(() => import("@/pages/DevSpriteLab"))
  : null;

function AppRoutes({ location }) {
  return (
    <Routes location={location}>
      <Route path="/" element={<LegacyRedirect pathname="/market" />} />
      <Route path="/market" element={<ListingsPage />} />
      <Route path="/listings" element={<LegacyRedirect pathname="/market" />} />
      <Route path="/saved" element={<SavedPage />} />
      <Route path="/favorites" element={<Navigate to="/saved?tab=watchlists" replace />} />
      <Route path="/alerts" element={<Navigate to="/saved?tab=alerts" replace />} />
      <Route path="/trading-history" element={<Navigate to="/saved?tab=recent" replace />} />
      <Route path="/compare" element={<ComparePage />} />
      <Route path="/shops" element={<ShopsPage />} />
      <Route path="/item/:key" element={<ItemDetail />} />
      <Route path="/lookup" element={<LookupPage />} />
      <Route path="/sellers" element={<SellersPage />} />
      <Route path="/sellers/:name" element={<SellerDetail />} />
      <Route path="/legal" element={<LegalPage />} />
      <Route path="/dashboard" element={<DashboardPage />} />
      <Route path="/settings" element={<SettingsPage />} />
      <Route path="/admin" element={<AdminPage />} />
      {process.env.NODE_ENV !== "production" && (
        <>
          <Route path="/dev/cards" element={<DevCards />} />
          <Route path="/dev/sprites" element={<DevSpriteLab />} />
        </>
      )}
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  );
}

function LegacyRedirect({ pathname }) {
  const location = useLocation();
  return <Navigate to={{ pathname, search: location.search }} replace />;
}

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "instant" });
  }, [pathname]);
  return null;
}

function AnimatedRoutes() {
  const location = useLocation();
  const prefersReduced = useReducedMotion();
  useAmbientMotion();
  // Everyday navigation (market <-> item hops) stays instant: a short
  // opacity-only fade with no exit wait. Full page transitions were
  // adding ~300ms of perceived latency to every route change.
  if (prefersReduced) {
    return (
      <Suspense fallback={<PageSkeleton />}>
        <AppRoutes location={location} />
      </Suspense>
    );
  }
  return (
    <motion.div
      key={location.pathname}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.12 }}
    >
      <Suspense fallback={<PageSkeleton />}>
        <AppRoutes location={location} />
      </Suspense>
    </motion.div>
  );
}

function RoutedErrorBoundary({ children }) {
  const { pathname } = useLocation();
  return (
    <ErrorBoundary key={pathname} resetKey={pathname}>
      {children}
    </ErrorBoundary>
  );
}

function App() {
  return (
    <div className="App">
      <BrowserRouter basename={process.env.PUBLIC_URL}>
        <a
          href="#main-content"
          onClick={(e) => {
            const main = document.querySelector("main");
            if (!main) return;
            e.preventDefault();
            if (!main.hasAttribute("tabindex")) main.setAttribute("tabindex", "-1");
            main.focus({ preventScroll: false });
          }}
          className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-[300] focus:rounded-md focus:bg-emerald-500 focus:px-4 focus:py-2 focus:font-mono focus:text-xs focus:font-bold focus:uppercase focus:tracking-wider focus:text-black"
        >
          Skip to content
        </a>
        <ScrollToTop />
        <MarketProvider>
          <RoutedErrorBoundary>
            <AnimatedRoutes />
          </RoutedErrorBoundary>
          <RecoverableDrawer />
          <ErrorBoundary fallback={null}>
            <CompareTray />
          </ErrorBoundary>
          <ErrorBoundary fallback={null}>
            <CommandPalette />
          </ErrorBoundary>
          <KeyboardHelpModal />
          <BackToTop />
          <InstallPrompt />
          <VersionPrompt />
          <Toaster />
        </MarketProvider>
      </BrowserRouter>
    </div>
  );
}

function RecoverableDrawer() {
  const location = useLocation();
  return <ErrorBoundary resetKey={`${location.pathname}${location.search}`}
    fallback={({ reset }) => <InlineFallback message="Detail panel failed to load." onReset={reset} />}>
    <DetailDrawer />
  </ErrorBoundary>;
}

export default App;
