import { useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import { Toaster as Sonner, toast } from "sonner";

export const Toaster = (props) => {
  const [theme, setTheme] = useState(() =>
    typeof document !== "undefined" && document.documentElement.classList.contains("dark") ? "dark" : "light"
  );

  useEffect(() => {
    const observer = new MutationObserver(() => {
      const isDark = document.documentElement.classList.contains("dark");
      setTheme(isDark ? "dark" : "light");
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, []);

  // Bottom-anchored toasts cover the Compare tray pill on touch devices,
  // so use top-center there and keep bottom-right on desktop.
  const [position, setPosition] = useState("bottom-right");
  useEffect(() => {
    try {
      if (window.matchMedia("(pointer: coarse)").matches) setPosition("top-center");
    } catch { /* ignore */ }
  }, []);

  // Top-center toasts land on the drawer's sticky header (close button)
  // on mobile — push them below it while any drawer panel is open.
  const [searchParams] = useSearchParams();
  const drawerOpen = ["item", "sellerView", "shopItem", "shopLocation"].some((k) =>
    searchParams.has(k)
  );

  return (
    <Sonner
      theme={theme}
      className="toaster group"
      position={position}
      offset={drawerOpen && position === "top-center" ? 76 : undefined}
      toastOptions={{
        classNames: {
          toast: `group toast border font-mono text-sm ${
            theme === "dark"
              ? "bg-bg-base text-white border-white/15 shadow-[0_8px_32px_rgba(0,0,0,0.5)]"
              : "bg-white text-zinc-900 border-zinc-200 shadow-[0_8px_32px_rgba(0,0,0,0.1)]"
          }`,
          description: theme === "dark" ? "text-zinc-400" : "text-zinc-500",
          actionButton: "bg-emerald-500 text-black",
          cancelButton: theme === "dark" ? "bg-white/10 text-white" : "bg-zinc-100 text-zinc-700",
        },
      }}
      {...props}
    />
  );
};

export { toast };
